const STAGE_LEDGER_EMIT_ATTEMPTS: usize = 3;

fn stage_ledger_error_should_retry_same_emitter(error: &crate::event_emitter::EmitError) -> bool {
    matches!(
        error,
        crate::event_emitter::EmitError::Backpressure(_)
            | crate::event_emitter::EmitError::Transport(_)
            | crate::event_emitter::EmitError::PersistenceTimeout { .. }
    )
}

/// Once the hsLink save is canonical, EVERY emit failure retains the exact receipt and in-flight lease.
/// No error class is permission to mint a replacement receipt or run capture again. Errors tied to an
/// emitter generation (NoRuntime/WorkerClosed/WorkspaceMismatch) recover by rebinding on operator retry.
fn stage_ledger_error_requires_retention(_error: &crate::event_emitter::EmitError) -> bool {
    true
}

fn stage_ledger_pending_outcome(
    pending: &PendingStageLedgerEmission,
    error: impl Into<String>,
) -> crate::stage_pane::EmbedBackOutcome {
    crate::stage_pane::EmbedBackOutcome::LedgerPending {
        artifact_id: pending.artifact_id.clone(),
        sha256: pending.sha256.clone(),
        target_pane: pending.target_pane.clone(),
        event_id: pending.receipt.event_id.clone(),
        error: error.into(),
    }
}

/// Preserve a committed Stage route receipt outside the generic bounded frame queue until EventLedger
/// durably acknowledges that exact event. Queue admission alone never clears the slot, and the Stage
/// pane admits no later route while it is occupied.
fn dispatch_or_retain_stage_route_receipt(
    ctx: &egui::Context,
    stage: &Arc<Mutex<StagePane>>,
    queue: &StageEmbedUiQueue,
    runtime: Option<tokio::runtime::Handle>,
    receipt: crate::event_emitter::NativeEditorEvent,
) -> bool {
    let attempt = if let Ok(mut pane) = stage.lock() {
        pane.retain_route_receipt(receipt);
        pane.begin_route_receipt_attempt()
    } else {
        None
    };
    let Some(receipt) = attempt else {
        return false;
    };
    let Some(runtime) = runtime else {
        if let Ok(mut pane) = stage.lock() {
            pane.finish_route_receipt_attempt(&receipt.event_id, false);
        }
        return false;
    };
    let bus = crate::interop::InteractionBus::get_or_init(ctx);
    let emitter = crate::interop::InteractionBus::with_try_lock(&bus, |bus| {
        bus.event_emitter()
            .filter(|emitter| emitter.workspace_id() == receipt.workspace_id)
            .cloned()
    })
    .flatten();
    let Some(emitter) = emitter else {
        if let Ok(mut pane) = stage.lock() {
            pane.finish_route_receipt_attempt(&receipt.event_id, false);
        }
        return false;
    };
    let queue = Arc::clone(queue);
    let repaint = ctx.clone();
    runtime.spawn(async move {
        let result = emitter
            .emit_persisted(receipt.clone(), std::time::Duration::from_secs(10))
            .await;
        queue
            .lock()
            .unwrap_or_else(|error| error.into_inner())
            .push(StageEmbedUiCompletion::RouteLedger {
                receipt,
                emitter,
                result,
            });
        repaint.request_repaint();
    });
    true
}

fn apply_stage_route_ledger_completion(
    ctx: &egui::Context,
    stage: &Arc<Mutex<StagePane>>,
    receipt: crate::event_emitter::NativeEditorEvent,
    emitter: crate::event_emitter::NativeEditorEventEmitter,
    result: Result<crate::event_emitter::NativeEditorEvent, crate::event_emitter::EmitError>,
) -> Option<StageEmbedUiCompletion> {
    let persisted = matches!(
        result.as_ref(),
        Ok(acknowledged) if acknowledged.event_id == receipt.event_id
    );
    if persisted {
        let acknowledged = result
            .as_ref()
            .expect("persisted Stage route result was matched above");
        let bus = crate::interop::InteractionBus::get_or_init(ctx);
        let callback_dispatched = crate::interop::InteractionBus::with_try_lock(&bus, |bus| {
            bus.surface_registry()
                .dispatch_event_emitted(acknowledged, &emitter);
        })
        .is_some();
        if !callback_dispatched {
            return Some(StageEmbedUiCompletion::RouteLedger {
                receipt,
                emitter,
                result,
            });
        }
    }
    if let Ok(mut pane) = stage.lock() {
        pane.finish_route_receipt_attempt(&receipt.event_id, persisted);
    }
    None
}

/// Move a retained post-save receipt onto the currently installed emitter only when that emitter is
/// live for the receipt's immutable workspace. The event itself is never rewritten.
fn rebind_stage_ledger_emitter_from_bus(
    ctx: &egui::Context,
    pending: &mut PendingStageLedgerEmission,
) -> bool {
    let bus = crate::interop::InteractionBus::get_or_init(ctx);
    let live = crate::interop::InteractionBus::with_try_lock(&bus, |bus| {
        bus.event_emitter()
            .filter(|emitter| emitter.workspace_id() == pending.workspace_id)
            .cloned()
    })
    .flatten();
    if let Some(emitter) = live {
        pending.emitter = emitter;
        true
    } else {
        false
    }
}

/// Run a bounded same-identity persistence retry off the frame thread. `pending.receipt` is cloned for
/// each attempt, preserving every payload field and the event_id. The completion always returns through
/// the UI queue; this task never mutates Stage/editor state.
async fn emit_stage_ledger_with_retry(
    pending: &PendingStageLedgerEmission,
    timeout: std::time::Duration,
    max_attempts: usize,
) -> Result<crate::event_emitter::NativeEditorEvent, crate::event_emitter::EmitError> {
    let mut attempt = 0usize;
    loop {
        attempt += 1;
        let result = pending
            .emitter
            .emit_persisted(pending.receipt.clone(), timeout)
            .await;
        let retry = result
            .as_ref()
            .err()
            .is_some_and(stage_ledger_error_should_retry_same_emitter)
            && attempt < max_attempts.max(1);
        if !retry {
            return result;
        }
        tokio::time::sleep(std::time::Duration::from_millis(150 * attempt as u64)).await;
    }
}

fn spawn_stage_ledger_emit(
    runtime: tokio::runtime::Handle,
    queue: StageEmbedUiQueue,
    repaint: egui::Context,
    pending: PendingStageLedgerEmission,
) {
    runtime.spawn(async move {
        let result = emit_stage_ledger_with_retry(
            &pending,
            std::time::Duration::from_secs(10),
            STAGE_LEDGER_EMIT_ATTEMPTS,
        )
        .await;
        let mut queue = queue.lock().unwrap_or_else(|error| error.into_inner());
        queue.push(StageEmbedUiCompletion::Ledger { pending, result });
        drop(queue);
        repaint.request_repaint();
    });
}

