fn take_current_code_ref_delivery(
    queue: &mut VecDeque<CodeRefNavDelivery>,
    pending: &HashMap<CodeNavigationScope, (u64, String)>,
) -> Option<CodeRefNavDelivery> {
    // Reject stale completions only inside their pane/source lane. A current completion from pane A
    // must survive while pane B supersedes B-old with B-new.
    queue.retain(|delivery| {
        pending
            .get(&delivery.operation.scope())
            .is_some_and(|(generation, _)| *generation == delivery.operation.generation)
    });
    queue.pop_front()
}

fn navigate_code_panel_to_target(
    panel: &CodeEditorPanel,
    fallback_line: usize,
    explicit_byte_offset: Option<usize>,
) {
    if let Some(byte_offset) = explicit_byte_offset {
        panel.navigate_to_byte_offset(byte_offset);
    } else {
        panel.navigate_to_line(fallback_line);
    }
}

fn rename_delivery_is_current(
    pending: Option<&PendingRename>,
    delivery: &crate::backend_client::RenameDelivery,
) -> bool {
    pending.is_some_and(|pending| {
        pending.operation_id == Some(delivery.operation.operation_id)
            && pending.target.entity_key() == delivery.operation.entity_key
    })
}

#[cfg(test)]
mod code_ref_nav_delivery_tests {
    use super::{
        take_current_code_ref_delivery, CodeNavigationScope, CodeRefNavDelivery,
        CodeRefNavigationOperation,
    };
    use std::collections::{HashMap, VecDeque};

    fn delivery(generation: u64, symbol: &str) -> CodeRefNavDelivery {
        CodeRefNavDelivery {
            operation: CodeRefNavigationOperation {
                generation,
                symbol_entity_id: symbol.to_owned(),
                source_file_hint: format!("{symbol}.rs"),
                origin_pane: None,
                origin_content_id: String::new(),
                source_panel: std::sync::Arc::new(crate::code_editor::panel::CodeEditorPanel::new(
                    "", "rs",
                )),
                explicit_byte_offset: None,
                preserve_origin: false,
                workspace_id: "workspace".to_owned(),
                origin_rich_view: None,
            },
            resolved: Err(crate::interop::cross_ref::CrossRefError::Backend(format!(
                "delivery-{generation}"
            ))),
        }
    }

    #[test]
    fn reverse_completion_cannot_overwrite_or_lose_newest_code_ref_navigation() {
        let mut queue = VecDeque::new();
        queue.push_back(delivery(2, "newest"));
        queue.push_back(delivery(1, "stale"));
        let scope = CodeNavigationScope::new(None, "");
        let pending = HashMap::from([(scope.clone(), (2, "newest".to_owned()))]);

        let selected = take_current_code_ref_delivery(&mut queue, &pending)
            .expect("the newest generation remains selectable even when stale completes last");
        assert_eq!(selected.operation.generation, 2);
        assert_eq!(selected.operation.symbol_entity_id, "newest");
        assert!(queue.is_empty(), "stale completions are discarded");

        let mut stale_first = VecDeque::from([delivery(1, "stale")]);
        assert!(take_current_code_ref_delivery(&mut stale_first, &pending).is_none());
        stale_first.push_back(delivery(2, "newest"));
        assert_eq!(
            take_current_code_ref_delivery(&mut stale_first, &pending)
                .expect("a later newest completion remains deliverable")
                .operation
                .symbol_entity_id,
            "newest"
        );
    }

    #[test]
    fn async_delivery_retains_exact_pane_panel_and_byte_target() {
        let mut queue = VecDeque::from([delivery(4, "exact")]);
        let pending =
            HashMap::from([(CodeNavigationScope::new(None, ""), (4, "exact".to_owned()))]);
        let mut exact = take_current_code_ref_delivery(&mut queue, &pending).expect("delivery");
        exact.operation.origin_pane = Some(std::sync::Arc::<str>::from("pane-2"));
        exact.operation.explicit_byte_offset = Some(0);
        let other = crate::code_editor::panel::CodeEditorPanel::new("0123456789", "txt");
        other.navigate_to_byte_offset(9);
        exact.operation.source_panel.navigate_to_byte_offset(0);

        super::navigate_code_panel_to_target(
            &exact.operation.source_panel,
            99,
            exact.operation.explicit_byte_offset,
        );

        assert_eq!(exact.operation.origin_pane.as_deref(), Some("pane-2"));
        assert_eq!(exact.operation.explicit_byte_offset, Some(0));
        assert_eq!(exact.operation.source_panel.primary_cursor_byte_offset(), 0);
        assert_eq!(other.primary_cursor_byte_offset(), 9);
    }

    #[test]
    fn resolver_delivery_correlation_is_pane_and_source_scoped() {
        let pane_a = std::sync::Arc::<str>::from("pane-a");
        let pane_b = std::sync::Arc::<str>::from("pane-b");
        let mut a = delivery(1, "a-current");
        a.operation.origin_pane = Some(pane_a.clone());
        a.operation.origin_content_id = "source-a".into();
        let mut b_old = delivery(2, "b-old");
        b_old.operation.origin_pane = Some(pane_b.clone());
        b_old.operation.origin_content_id = "source-b".into();
        let mut b_new = delivery(3, "b-new");
        b_new.operation.origin_pane = Some(pane_b.clone());
        b_new.operation.origin_content_id = "source-b".into();
        let mut queue = VecDeque::from([b_old, a, b_new]);
        let pending = HashMap::from([
            (
                CodeNavigationScope::new(Some(pane_a), "source-a"),
                (1, "a-current".to_owned()),
            ),
            (
                CodeNavigationScope::new(Some(pane_b), "source-b"),
                (3, "b-new".to_owned()),
            ),
        ]);

        assert_eq!(
            take_current_code_ref_delivery(&mut queue, &pending)
                .expect("pane A completion survives pane B supersession")
                .operation
                .symbol_entity_id,
            "a-current"
        );
        assert_eq!(
            take_current_code_ref_delivery(&mut queue, &pending)
                .expect("pane B newest completion lands")
                .operation
                .symbol_entity_id,
            "b-new"
        );
        assert!(queue.is_empty(), "B-old was rejected only inside B's lane");
    }
}

#[cfg(test)]
mod rename_delivery_tests {
    use super::{rename_delivery_is_current, ExplorerRenameTarget, PendingRename};
    use crate::backend_client::{RenameDelivery, RenameOperation};
    use std::collections::VecDeque;

    fn pending(document_id: &str, operation_id: Option<u64>) -> PendingRename {
        PendingRename {
            target: ExplorerRenameTarget::Document {
                document_id: document_id.to_owned(),
                expected_updated_at: Some("token".to_owned()),
            },
            text: "Title".to_owned(),
            operation_id,
        }
    }

    fn delivery(document_id: &str, operation_id: u64) -> RenameDelivery {
        RenameDelivery {
            operation: RenameOperation {
                operation_id,
                entity_key: format!("rich-document:{document_id}"),
            },
            result: Ok("Renamed".to_owned()),
        }
    }

    #[test]
    fn reverse_completion_only_matches_current_operation_and_entity() {
        let current = pending("KRD-new", Some(2));
        let queue = VecDeque::from([delivery("KRD-new", 2), delivery("KRD-old", 1)]);
        let accepted: Vec<_> = queue
            .iter()
            .filter(|item| rename_delivery_is_current(Some(&current), item))
            .map(|item| item.operation.operation_id)
            .collect();
        assert_eq!(accepted, vec![2]);
    }

    #[test]
    fn cancel_reopen_and_double_confirm_are_stale_safe() {
        let old = delivery("KRD-1", 1);
        assert!(
            !rename_delivery_is_current(None, &old),
            "cancel rejects late completion"
        );

        let reopened = pending("KRD-1", Some(2));
        assert!(
            !rename_delivery_is_current(Some(&reopened), &old),
            "reopen rejects the previous dialog's completion"
        );
        assert!(
            !rename_delivery_is_current(Some(&pending("KRD-1", None)), &old),
            "a dialog with no in-flight operation cannot accept duplicate completion"
        );
    }
}

#[cfg(test)]
mod mt067_calendar_delivery_identity_tests {
    use super::{HandshakeApp, HealthDisplayState};
    use crate::backend_client::HealthInfo;
    use crate::graph::daily_journal_panel::{
        CalendarProjectionState, CalendarReadFailure, DailyJournalState,
    };
    use crate::rich_editor::daily_notes::date_nav::DateNav;
    use chrono::{NaiveDate, TimeZone, Utc};
    use std::sync::atomic::AtomicU64;
    use std::sync::{Arc, Mutex};

    fn date(day: u32) -> NaiveDate {
        NaiveDate::from_ymd_opt(2026, 7, day).expect("valid test date")
    }

    #[test]
    fn reverse_completion_cannot_replace_the_newest_selected_calendar_date() {
        let first = date(20);
        let second = date(21);
        let state = Arc::new(Mutex::new(DailyJournalState::new(DateNav::new(
            first, first,
        ))));
        let generation = AtomicU64::new(2);
        state.lock().unwrap().prepare_date(second);

        assert!(
            !HandshakeApp::apply_calendar_delivery(&state, &generation, 1, first, |state| {
                state.set_calendar_unavailable();
            }),
            "a late first-date delivery is rejected after the second request supersedes it"
        );
        let state = state.lock().unwrap();
        assert_eq!(state.nav.current, second);
        assert_eq!(
            state.projection,
            CalendarProjectionState::WaitingForDailyNote
        );
    }

    #[test]
    fn matching_generation_still_requires_the_exact_selected_date() {
        let first = date(20);
        let second = date(21);
        let state = Arc::new(Mutex::new(DailyJournalState::new(DateNav::new(
            second, second,
        ))));
        let generation = AtomicU64::new(3);

        assert!(
            !HandshakeApp::apply_calendar_delivery(&state, &generation, 3, first, |state| {
                state.set_calendar_unavailable();
            }),
            "generation equality alone cannot authorize a response for a different date"
        );
        assert!(HandshakeApp::apply_calendar_delivery(
            &state,
            &generation,
            3,
            second,
            |state| state.set_calendar_unavailable(),
        ));
        assert_eq!(
            state.lock().unwrap().projection,
            CalendarProjectionState::Failed(CalendarReadFailure::EndpointUnavailable)
        );
    }

    #[test]
    fn workspace_rebind_invalidates_cached_calendar_request_before_new_journal_load() {
        let mut app = HandshakeApp::with_health(HealthDisplayState::Ok(HealthInfo {
            status: "ok".to_owned(),
            db_status: "ok".to_owned(),
            migration_version: Some(1),
        }));
        app.calendar_fetch_key = Some(("workspace-a".to_owned(), date(20), 4, "UTC".to_owned()));
        app.calendar_request_generation
            .store(9, std::sync::atomic::Ordering::Release);

        app.invalidate_calendar_request();

        assert!(app.calendar_fetch_key.is_none());
        assert_eq!(
            app.calendar_request_generation
                .load(std::sync::atomic::Ordering::Acquire),
            10
        );
    }

    #[test]
    fn timezone_switch_invalidates_in_flight_request_and_rejects_stale_delivery() {
        let selected = date(20);
        let state = Arc::new(Mutex::new(DailyJournalState::new(DateNav::new(
            selected, selected,
        ))));
        state.lock().unwrap().begin_calendar_load(selected);
        let mut app = HandshakeApp::with_health(HealthDisplayState::Ok(HealthInfo {
            status: "ok".to_owned(),
            db_status: "ok".to_owned(),
            migration_version: Some(1),
        }));
        app.workspace_settings.calendar_view_tzid = "UTC".to_owned();
        app.calendar_fetch_key = Some(("workspace-a".to_owned(), selected, 4, "UTC".to_owned()));
        app.calendar_request_generation
            .store(9, std::sync::atomic::Ordering::Release);

        assert!(app.apply_settings_outcome(
            crate::settings_dialog::SettingsOutcome::CalendarTimezoneChanged(
                "Europe/Brussels".to_owned(),
            ),
        ));
        assert_eq!(app.workspace_settings.calendar_view_tzid, "Europe/Brussels");
        assert!(app.calendar_fetch_key.is_none());
        assert_eq!(
            app.calendar_request_generation
                .load(std::sync::atomic::Ordering::Acquire),
            10
        );
        assert!(
            !HandshakeApp::apply_calendar_delivery(
                &state,
                &app.calendar_request_generation,
                9,
                selected,
                |state| state.set_calendar_unavailable(),
            ),
            "the UTC response cannot publish after the selected view switches to Europe/Brussels"
        );
        assert_eq!(
            state.lock().unwrap().projection,
            CalendarProjectionState::Loading
        );
    }

    #[test]
    fn persisted_view_timezone_updates_today_on_both_reused_navigation_surfaces() {
        let mut app = HandshakeApp::with_health(HealthDisplayState::Ok(HealthInfo {
            status: "ok".to_owned(),
            db_status: "ok".to_owned(),
            migration_version: Some(1),
        }));
        let selected = date(20);
        app.editor_mounts
            .secondary
            .daily_journal
            .lock()
            .unwrap()
            .nav = DateNav::new(selected, selected);
        let store = crate::rich_editor::daily_notes::journal_store::JournalStore::headless(
            Arc::new(
                crate::rich_editor::daily_notes::journal_store::ReqwestJournalBackend::new(
                    "http://127.0.0.1:1",
                ),
            ),
            Arc::new(
                crate::rich_editor::daily_notes::journal_store::ReqwestSaveSeam::new(
                    "http://127.0.0.1:1",
                ),
            ),
        );
        let editor = crate::rich_editor::daily_notes::journal_panel::JournalPanelState::new(
            store,
            DateNav::new(selected, selected),
        );
        *app.editor_mounts.secondary.journal_slot.lock().unwrap() =
            Some(Arc::new(Mutex::new(editor)));

        app.workspace_settings.calendar_view_tzid = "Etc/GMT+5".to_owned();
        let instant = Utc.with_ymd_and_hms(2026, 7, 23, 0, 30, 0).unwrap();
        assert!(app.sync_calendar_today_at(instant));
        let expected = NaiveDate::from_ymd_opt(2026, 7, 22).unwrap();
        assert_eq!(
            app.editor_mounts
                .secondary
                .daily_journal
                .lock()
                .unwrap()
                .nav
                .today,
            expected
        );
        assert_eq!(
            app.editor_mounts
                .secondary
                .journal_slot
                .lock()
                .unwrap()
                .as_ref()
                .unwrap()
                .lock()
                .unwrap()
                .nav
                .today,
            expected
        );
        assert_eq!(
            crate::rich_editor::daily_notes::date_nav::today_in_timezone_at(instant, "UTC")
                .unwrap(),
            NaiveDate::from_ymd_opt(2026, 7, 23).unwrap(),
            "the controlled instant proves the UTC/local date split"
        );
    }
}

struct PendingCanvasPlacementCreateUndo {
    cell: crate::backend_client::CanvasBoardCreateCell,
    client: Arc<crate::backend_client::CanvasBoardClient>,
    workspace_id: String,
    canvas_block_id: String,
    /// Monotonic dispatch identity within the shell. Completion effects that represent operator-visible
    /// status (clear/set error) are accepted only when this is still the latest create for the board.
    operation_sequence: u64,
    description: String,
    /// WP-KERNEL-012 MT-080 FIX A: `true` when this create came from `CanvasEvent::AddCard` (a free-text
    /// card via `POST .../cards`), so when it resolves the host records the minted `placed_block_id` as a
    /// TextCard. `false` for a `PlaceBlock` (a reference to an existing block — never inline-editable).
    is_text_card: bool,
}

fn canvas_identity_matches(
    current: Option<&(String, String)>,
    workspace_id: &str,
    canvas_block_id: &str,
) -> bool {
    current
        .is_some_and(|(workspace, canvas)| workspace == workspace_id && canvas == canvas_block_id)
}

#[cfg(test)]
mod mt033_canvas_completion_identity_tests {
    use super::canvas_identity_matches;
    use std::collections::HashMap;

    #[test]
    fn failed_a_completion_never_paints_b_and_reappears_on_return_to_a() {
        let a = ("workspace".to_owned(), "canvas-a".to_owned());
        let b = ("workspace".to_owned(), "canvas-b".to_owned());
        let mut errors = HashMap::new();
        assert!(!canvas_identity_matches(Some(&b), &a.0, &a.1));
        errors.insert(a.clone(), "A placement failed".to_owned());
        assert!(
            !errors.contains_key(&b),
            "canvas B receives no canvas A error"
        );
        assert!(canvas_identity_matches(Some(&a), &a.0, &a.1));
        assert_eq!(
            errors.get(&a).map(String::as_str),
            Some("A placement failed")
        );
    }

    #[test]
    fn successful_a_completion_while_b_is_current_clears_only_a_error() {
        let a = ("workspace".to_owned(), "canvas-a".to_owned());
        let b = ("workspace".to_owned(), "canvas-b".to_owned());
        let mut errors = HashMap::from([
            (a.clone(), "old A failure".to_owned()),
            (b.clone(), "existing B failure".to_owned()),
        ]);
        assert!(!canvas_identity_matches(Some(&b), &a.0, &a.1));
        errors.remove(&a);
        assert!(!errors.contains_key(&a));
        assert_eq!(
            errors.get(&b).map(String::as_str),
            Some("existing B failure")
        );
        assert!(canvas_identity_matches(Some(&a), &a.0, &a.1));
    }
}

