    /// Open/focus the one docked Stage factory. `stage_panel_open` remains the observable logical
    /// route-open flag for compatibility, but no second bottom host is rendered.
    fn open_stage_surface(&mut self, ctx: &egui::Context) {
        self.remember_stage_embed_target();
        self.stage_panel_open = true;
        let stage_type = crate::editor_pane_factories::placeholder_pane_type(
            crate::editor_pane_factories::STAGE_PANE_LABEL,
        );
        if !self.activate_unique_stage_tab(&stage_type) {
            self.open_content_on_active_pane(stage_type, None);
        }
        ctx.request_repaint();
    }

    /// Retain the exact editor active before Stage takes over its tab. A Stage-to-Stage open leaves the
    /// previous target intact so the in-pane embed action returns to the original editor.
    fn remember_stage_embed_target(&mut self) {
        let Some(pane_id) = self.active_pane.as_ref() else {
            return;
        };
        let Some(tab) = self
            .tab_bar_states
            .get(pane_id)
            .and_then(|bar| bar.active())
        else {
            return;
        };
        if tab.pane_type
            == crate::editor_pane_factories::placeholder_pane_type(
                crate::editor_pane_factories::STAGE_PANE_LABEL,
            )
        {
            return;
        }

        let pane_id = pane_id.as_ref().to_owned();
        let target = if tab.pane_type == PaneType::AtelierEditor {
            tab.content_id
                .clone()
                .filter(|id| !id.trim().is_empty())
                .or_else(|| {
                    self.editor_mounts
                        .secondary
                        .canvas_board
                        .lock()
                        .ok()
                        .map(|board| board.canvas_block_id.clone())
                        .filter(|id| !id.trim().is_empty())
                })
                .map(|canvas_id| crate::stage_pane::EmbedTarget::Canvas { pane_id, canvas_id })
        } else {
            self.active_rich_document_id()
                .filter(|id| !id.trim().is_empty())
                .map(|document_id| crate::stage_pane::EmbedTarget::Note {
                    pane_id,
                    document_id,
                })
        };
        if let Some(target) = target {
            if self.stage_embed_target.as_ref() != Some(&target) {
                self.stage_embed_target = Some(target);
                self.stage_embed_target_epoch
                    .fetch_add(1, std::sync::atomic::Ordering::AcqRel);
            }
        }
    }

    fn retained_stage_embed_target_is_live(&self, target: &crate::stage_pane::EmbedTarget) -> bool {
        match target {
            crate::stage_pane::EmbedTarget::Note {
                pane_id,
                document_id,
            } => self
                .tab_bar_states
                .get(&PaneId::from(pane_id.as_str()))
                .is_some_and(|bar| {
                    bar.tabs.iter().any(|tab| {
                        tab.pane_type == PaneType::LoomWikiPage
                            && tab.content_id.as_deref() == Some(document_id.as_str())
                    })
                }),
            crate::stage_pane::EmbedTarget::Canvas { pane_id, canvas_id } => {
                let tab_live = self
                    .tab_bar_states
                    .get(&PaneId::from(pane_id.as_str()))
                    .is_some_and(|bar| {
                        bar.tabs
                            .iter()
                            .any(|tab| tab.pane_type == PaneType::AtelierEditor)
                    });
                let board_live = self
                    .editor_mounts
                    .secondary
                    .canvas_board
                    .lock()
                    .map(|board| board.canvas_block_id == *canvas_id)
                    .unwrap_or(false);
                tab_live && board_live
            }
        }
    }

    fn invalidate_stale_stage_embed_target(&mut self) {
        let stale = self
            .stage_embed_target
            .as_ref()
            .is_some_and(|target| !self.retained_stage_embed_target_is_live(target));
        if stale {
            self.stage_embed_target = None;
            self.stage_embed_target_epoch
                .fetch_add(1, std::sync::atomic::Ordering::AcqRel);
        }
    }

    /// Focus the shell-wide Stage tab and remove duplicate Stage tabs left by older pane-local open
    /// behavior. A stable `stage-pane` AccessKit id must identify exactly one live host regardless of
    /// which editor pane was active when Stage was opened or routed.
    fn activate_unique_stage_tab(&mut self, stage_type: &PaneType) -> bool {
        let mut pane_ids = self.tab_bar_states.keys().cloned().collect::<Vec<_>>();
        pane_ids.sort();
        let Some(canonical_pane) = pane_ids.iter().find_map(|pane_id| {
            self.tab_bar_states.get(pane_id).and_then(|bar| {
                bar.tabs
                    .iter()
                    .any(|tab| tab.pane_type == *stage_type && tab.content_id.is_none())
                    .then(|| pane_id.clone())
            })
        }) else {
            return false;
        };

        for pane_id in pane_ids {
            let Some(bar) = self.tab_bar_states.get_mut(&pane_id) else {
                continue;
            };
            let stage_indices = bar
                .tabs
                .iter()
                .enumerate()
                .filter_map(|(index, tab)| {
                    (tab.pane_type == *stage_type && tab.content_id.is_none()).then_some(index)
                })
                .collect::<Vec<_>>();
            if pane_id == canonical_pane {
                if let Some(&index) = stage_indices.first() {
                    for &duplicate in stage_indices.iter().skip(1).rev() {
                        let _ = bar.take_tab(duplicate);
                    }
                    bar.activate(index);
                }
            } else {
                for &index in stage_indices.iter().rev() {
                    let _ = bar.take_tab(index);
                }
            }
        }
        self.active_pane = Some(canonical_pane);
        true
    }

    /// A clonable producer handle onto the shell event bus (MT-014 FIX-B). A future surface that
    /// performs a delete (document / canvas / bookmark) clones this and publishes a [`ShellEvent`] so
    /// the project tree drops the row on the next frame. No production emitter exists yet (FIX-B); this
    /// is the wired entry point for one.
    pub fn event_bus_sender(&self) -> ShellEventSender {
        self.event_bus_tx.clone()
    }

    /// Drain the shell event bus (MT-014 FIX-B) and apply each event to the live project tree so a
    /// document / canvas / bookmark deleted from another surface disappears with no stale row. Called
    /// once per frame at the top of [`ui`](Self::ui), before the tree renders. Returns the number of
    /// events that actually removed a row (for tests / repaint scheduling).
    pub fn drain_shell_events(&mut self) -> usize {
        // MT-027: a snapshot-capture pass must not consume the shell event bus (the real frame owns it).
        if self.capturing_snapshot {
            return 0;
        }
        let events = self.event_bus_rx.drain();
        let mut removed = 0usize;
        for event in events {
            let did_remove = match event {
                ShellEvent::DocumentDeleted { document_id } => {
                    self.left_rail.project_tree.remove_document(&document_id)
                }
                ShellEvent::CanvasDeleted { canvas_id } => {
                    self.left_rail.project_tree.remove_canvas(&canvas_id)
                }
                ShellEvent::BookmarkRemoved { block_id } => {
                    self.left_rail.project_tree.remove_bookmark(&block_id)
                }
                ShellEvent::FavoriteRemoved { .. } => false,
            };
            if did_remove {
                removed += 1;
            }
        }
        removed
    }

