    /// Bind a managed-workspace id for an external integration harness without invoking the project
    /// layout persistence lifecycle. This keeps live pane proofs on the real [`HandshakeApp::ui`] host
    /// while avoiding a fabricated project-tab click; production navigation uses the normal project
    /// switch path.
    pub fn bind_active_project_for_integration_test(&mut self, workspace_id: impl Into<String>) {
        let workspace_id = workspace_id.into();
        self.active_project_id = workspace_id.clone();
        self.project_tabs.set_active_id(workspace_id.clone());
        if let Ok(mut shared) = self.find_in_files_shared.lock() {
            if shared.workspace_id.as_deref() != Some(workspace_id.as_str()) {
                shared.workspace_generation = shared.workspace_generation.wrapping_add(1);
                shared.open_requests.clear();
                shared.bookmarks_loaded_for.clear();
            }
            shared.workspace_id = Some(workspace_id);
        }
        // Bind/retire document state at the workspace transition itself. Deferring this until a GET
        // delivery can invalidate an Arc already returned to the mounted host, leaving that visible
        // view permanently detached from the state which receives the loaded document.
        self.ensure_rich_document_workspace();
    }

    /// Clear the ephemeral FEMS overlay and any in-flight FEMS deliveries from a mounted integration
    /// harness. Cross-feature visual proofs use this after the normal project-rebind frame so an
    /// unrelated pending-review transport failure cannot obscure the feature under inspection. This
    /// deliberately does not change persisted memory state or the active project.
    pub fn clear_fems_overlay_for_integration_test(&mut self) {
        self.invalidate_memory_proposal_state_on_workspace_change();
    }

    /// Remove only a terminal, incidental pending-review notice from a cross-feature integration
    /// proof. A managed-workspace bind starts the canonical FEMS review refresh; its terminal
    /// transport failure must not obscure another feature's screenshot, but this seam must never
    /// cancel an open proposal, submission, review decision, or in-flight refresh.
    ///
    /// Returns `false` until the background refresh has terminalized or whenever operator-owned FEMS
    /// state exists. The caller can therefore wait without reaching into MT-064 internals.
    #[doc(hidden)]
    pub fn clear_incidental_fems_notice_for_integration_test(&mut self) -> bool {
        if self.pending_memory_proposal.is_some()
            || self.pending_memory_proposal_emitter.is_some()
            || self.memory_proposal_operation.is_some()
            || self.memory_proposal_submit_pending
            || self.memory_proposal_review_target.is_some()
            || self.memory_proposal_review_operation.is_some()
            || self.memory_proposal_review_refresh.is_some()
            || self.memory_proposal_review_refresh_deferred.is_some()
        {
            return false;
        }

        self.memory_proposal_status = None;
        self.memory_proposal_status_value = None;
        self.memory_proposal_review_retry = None;
        true
    }

