    fn active_code_panel_and_content_id(&self) -> (String, Arc<CodeEditorPanel>) {
        let active_tab = self
            .active_pane
            .as_ref()
            .and_then(|pane_id| self.tab_bar_states.get(pane_id))
            .and_then(TabBarState::active)
            .filter(|tab| matches!(tab.pane_type, PaneType::CodeSymbol));
        let requested_id = active_tab
            .and_then(|tab| tab.content_id.clone())
            .unwrap_or_default();
        let content_id = if self.editor_mounts.code_documents.contains(&requested_id) {
            requested_id
        } else {
            String::new()
        };
        let panel = self
            .editor_mounts
            .code_documents
            .panel_for_content_id((!content_id.is_empty()).then_some(content_id.as_str()));
        (content_id, panel)
    }

    /// Locate the pane whose active code tab owns `content_id`. This is more reliable than the
    /// shell's transient focus hint when a code-panel action is drained before the split layout has
    /// marked a pane active in the current frame.
    fn pane_for_active_code_content_id(&self, content_id: &str) -> Option<PaneId> {
        let mut panes: Vec<PaneId> = self
            .tab_bar_states
            .iter()
            .filter(|(_, bar)| {
                bar.active().is_some_and(|tab| {
                    let requested_id = tab.content_id.as_deref().unwrap_or_default();
                    let mounted_id = if self.editor_mounts.code_documents.contains(requested_id) {
                        requested_id
                    } else {
                        ""
                    };
                    matches!(tab.pane_type, PaneType::CodeSymbol) && mounted_id == content_id
                })
            })
            .map(|(pane_id, _)| pane_id.clone())
            .collect();
        panes.sort_by(|left, right| left.as_ref().cmp(right.as_ref()));
        panes.into_iter().next()
    }

    fn is_code_document_open(&self, content_id: &str) -> bool {
        self.tab_bar_states.values().any(|bar| {
            bar.tabs.iter().any(|tab| {
                if !matches!(tab.pane_type, PaneType::CodeSymbol) {
                    return false;
                }
                let requested = tab.content_id.as_deref().unwrap_or_default();
                let mounted = if self.editor_mounts.code_documents.contains(requested) {
                    requested
                } else {
                    ""
                };
                mounted == content_id
            })
        })
    }

    fn code_command_source_is_open(&self, command: &CodeEditorHostCommand) -> bool {
        let matches_document = |tab: &TabState| {
            if !matches!(tab.pane_type, PaneType::CodeSymbol) {
                return false;
            }
            let requested = tab.content_id.as_deref().unwrap_or_default();
            let mounted = if self.editor_mounts.code_documents.contains(requested) {
                requested
            } else {
                ""
            };
            mounted == command.document_id
        };
        if let Some(pane_id) = command.pane_id.as_ref() {
            self.tab_bar_states
                .get(pane_id)
                .is_some_and(|bar| bar.tabs.iter().any(matches_document))
        } else {
            self.tab_bar_states
                .values()
                .any(|bar| bar.tabs.iter().any(matches_document))
        }
    }

    fn refresh_code_document_context_epoch(&mut self) {
        let (content_id, _) = self.active_code_panel_and_content_id();
        let current = (self.active_pane.clone(), content_id);
        if self.code_document_last_context.as_ref() != Some(&current) {
            self.code_document_context_epoch = self.code_document_context_epoch.wrapping_add(1);
            self.code_document_last_context = Some(current);
        }
    }

    fn code_navigation_source_is_current(
        &self,
        origin_pane: Option<&PaneId>,
        origin_content_id: &str,
        origin_context_epoch: u64,
    ) -> bool {
        let detached_origin =
            origin_pane.is_some_and(|pane_id| self.popout_manager.is_popped_out(pane_id));
        let origin_tab_is_current = origin_pane.is_none_or(|pane_id| {
            self.tab_bar_states.get(pane_id).is_some_and(|bar| {
                bar.active().is_some_and(|tab| {
                    let requested_id = tab.content_id.as_deref().unwrap_or_default();
                    let mounted_id = if self.editor_mounts.code_documents.contains(requested_id) {
                        requested_id
                    } else {
                        ""
                    };
                    matches!(tab.pane_type, PaneType::CodeSymbol) && mounted_id == origin_content_id
                })
            })
        });
        if detached_origin {
            return origin_tab_is_current;
        }
        let (active_content_id, _) = self.active_code_panel_and_content_id();
        origin_tab_is_current
            && (origin_pane.is_none()
                || self.active_pane.is_none()
                || origin_pane == self.active_pane.as_ref())
            && active_content_id == origin_content_id
            && origin_context_epoch == self.code_document_context_epoch
    }

