    /// Open the concrete wiki projection last bound for the active workspace. If the binding belongs to
    /// another workspace (or no projection is bound), open truthful wiki discovery instead of carrying
    /// stale cross-workspace identity into a pane that cannot load or save the requested page.
    fn open_active_wiki_projection_or_discovery(&mut self, ctx: &egui::Context) -> bool {
        let active_workspace_id = self.active_project_id.trim();
        let projection_id = self
            .editor_mounts
            .secondary
            .wiki_bound
            .lock()
            .ok()
            .and_then(|bound| {
                bound.as_ref().and_then(|(identity, _)| {
                    (!active_workspace_id.is_empty()
                        && identity.workspace_id == active_workspace_id
                        && !identity.projection_id.trim().is_empty())
                    .then(|| identity.projection_id.clone())
                })
            });
        if let Some(projection_id) = projection_id {
            return self.open_content_on_active_pane(
                crate::editor_pane_factories::placeholder_pane_type(
                    crate::editor_pane_factories::WIKI_PAGE_PANE_LABEL,
                ),
                Some(projection_id),
            );
        }
        self.open_quick_switcher();
        crate::quick_switcher::prime_query(ctx, self.quick_switcher_open_count, "wiki");
        self.quick_switcher_nav_status =
            Some("No active wiki projection. Choose a wiki page from Quick Switcher.".to_owned());
        true
    }

