    /// Inject a completion for the exact request currently accepted by the mounted canvas host.
    pub fn deliver_canvas_board_for_test(
        &mut self,
        result: Result<crate::backend_client::CanvasBoardData, String>,
    ) {
        let request = if let Some(request) = self.canvas_expected_request.clone() {
            Some(request)
        } else {
            let board_key = self
                .editor_mounts
                .secondary
                .canvas_board
                .lock()
                .ok()
                .map(|board| (board.workspace_id.clone(), board.canvas_block_id.clone()));
            board_key.map(|(workspace_id, canvas_block_id)| {
                self.canvas_request_generation =
                    self.canvas_request_generation.wrapping_add(1).max(1);
                self.canvas_request_sequence = self.canvas_request_sequence.wrapping_add(1).max(1);
                let request = crate::backend_client::CanvasBoardRequestIdentity::new(
                    workspace_id,
                    canvas_block_id,
                    self.canvas_request_generation,
                    self.canvas_request_sequence,
                );
                self.canvas_expected_request = Some(request.clone());
                request
            })
        };
        if let Some(request) = request {
            self.deliver_canvas_board_request_for_test(request, result);
        }
    }

