    /// Advance the mounted host to a new logical board request without network I/O. This changes the
    /// same generation/sequence state as production dispatch and is used only to exercise reordered
    /// completions deterministically.
    pub fn begin_canvas_request_for_test(
        &mut self,
        workspace_id: impl Into<String>,
        canvas_block_id: impl Into<String>,
    ) -> crate::backend_client::CanvasBoardRequestIdentity {
        let workspace_id = workspace_id.into();
        let canvas_block_id = canvas_block_id.into();
        let binding_changed = self
            .canvas_expected_request
            .as_ref()
            .map(|request| {
                request.workspace_id != workspace_id || request.canvas_block_id != canvas_block_id
            })
            .unwrap_or(true);
        if binding_changed {
            self.canvas_request_generation = self.canvas_request_generation.wrapping_add(1).max(1);
        }
        self.canvas_request_sequence = self.canvas_request_sequence.wrapping_add(1).max(1);
        let request = crate::backend_client::CanvasBoardRequestIdentity::new(
            &workspace_id,
            &canvas_block_id,
            self.canvas_request_generation,
            self.canvas_request_sequence,
        );
        self.canvas_expected_request = Some(request.clone());
        self.active_project_id = workspace_id.clone();
        if let Ok(mut board) = self.editor_mounts.secondary.canvas_board.lock() {
            board.begin_projection_load(workspace_id, canvas_block_id);
        }
        request
    }

    /// WP-KERNEL-012 MT-080 FIX B: inject a graph delivery into the SAME shared cell the per-frame feed
    /// drain reads, so a host-mount proof can drive `set_graph` + the FIX B `apply_group_identity`
    /// group-colouring cross-reference without a live backend.
    pub fn deliver_graph_for_test(
        &mut self,
        result: Result<crate::backend_client::LoomGraphData, String>,
    ) {
        use crate::backend_client::LoomGraphRequestIdentity;
        use crate::graph::graph_view::GraphMode;

        self.graph_request_generation = self.graph_request_generation.wrapping_add(1).max(1);
        let (workspace_id, mode, depth) = self
            .editor_mounts
            .secondary
            .graph_view
            .lock()
            .map(|view| {
                (
                    view.workspace_id.clone(),
                    view.mode.clone(),
                    view.controls.link_depth,
                )
            })
            .unwrap_or_else(|_| (String::new(), GraphMode::Global, 2));
        let request = match mode {
            GraphMode::Global => {
                LoomGraphRequestIdentity::global(self.graph_request_generation, workspace_id)
            }
            GraphMode::Local { block_id, .. } => LoomGraphRequestIdentity::local(
                self.graph_request_generation,
                workspace_id,
                block_id,
                depth,
            ),
        };
        self.graph_expected_request = Some(request.clone());
        self.deliver_graph_request_for_test(request, result);
    }

