    /// WP-KERNEL-012 MT-035: inject a resolved canvas create response into the same pending-create drain
    /// production uses after `dispatch_created_placement` returns. This keeps the host proof off a live
    /// PostgreSQL dependency while still exercising the real frame drain and shared InteractionBus.
    pub fn deliver_canvas_created_placement_for_test(
        &mut self,
        workspace_id: impl Into<String>,
        canvas_block_id: impl Into<String>,
        result: crate::backend_client::CreatedCanvasPlacement,
        description: impl Into<String>,
        is_text_card: bool,
    ) -> Result<(), String> {
        let workspace_id = workspace_id.into();
        let canvas_block_id = canvas_block_id.into();
        let operation_sequence = self.next_canvas_create_sequence(&workspace_id, &canvas_block_id);
        self.deliver_canvas_created_placement_result_for_test(
            workspace_id,
            canvas_block_id,
            operation_sequence,
            Ok(result),
            description,
            is_text_card,
        )
    }

    /// Inject an explicitly sequenced completion into the production pending-create drain. The
    /// sequence is dispatch order, while insertion order is completion order; tests reverse them to
    /// prove stale same-board completions cannot overwrite the latest operator-visible result.
    pub fn deliver_canvas_created_placement_result_for_test(
        &mut self,
        workspace_id: impl Into<String>,
        canvas_block_id: impl Into<String>,
        operation_sequence: u64,
        result: Result<crate::backend_client::CreatedCanvasPlacement, String>,
        description: impl Into<String>,
        is_text_card: bool,
    ) -> Result<(), String> {
        let Some(rt) = self.runtime_handle.clone() else {
            return Err(
                "runtime handle is required for canvas compensating undo client".to_owned(),
            );
        };
        let workspace_id = workspace_id.into();
        let canvas_block_id = canvas_block_id.into();
        let key = (workspace_id.clone(), canvas_block_id.clone());
        self.canvas_create_sequence = self.canvas_create_sequence.max(operation_sequence);
        self.canvas_latest_create_sequence
            .entry(key)
            .and_modify(|latest| *latest = (*latest).max(operation_sequence))
            .or_insert(operation_sequence);
        let cell = Arc::new(Mutex::new(Some(result)));
        self.canvas_create_cells
            .push(PendingCanvasPlacementCreateUndo {
                cell,
                client: Arc::new(crate::backend_client::CanvasBoardClient::new(
                    &self.rich_doc_base_url,
                    rt,
                )),
                workspace_id,
                canvas_block_id,
                operation_sequence,
                description: description.into(),
                is_text_card,
            });
        Ok(())
    }

    /// Inject an async Canvas undo/redo completion into the exact FIFO drained by the production app.
    /// Used to prove board-attributed failure visibility across A -> B -> A without a live transport.
    pub fn deliver_canvas_compensation_for_test(
        &self,
        action_id: impl Into<String>,
        direction: crate::undo_stack::AsyncUndoDirection,
        workspace_id: impl Into<String>,
        canvas_block_id: impl Into<String>,
        result: Result<(), String>,
    ) {
        if let Ok(mut queue) = self.canvas_compensation_cell.lock() {
            queue.push_back(
                crate::graph::interop_adapter::CanvasCompensationCompletion {
                    action_id: action_id.into(),
                    direction,
                    reload: crate::graph::interop_adapter::CanvasBoardReloadIntent {
                        workspace_id: workspace_id.into(),
                        canvas_block_id: canvas_block_id.into(),
                    },
                    result,
                },
            );
        }
    }

