    fn pane_type_for(&self, pane_id: &PaneId) -> Option<PaneType> {
        self.tab_bar_states
            .get(pane_id)
            .and_then(|bar| bar.active())
            .map(|tab| tab.pane_type.clone())
            .or_else(|| {
                self.pane_registry
                    .lock()
                    .ok()
                    .and_then(|reg| reg.get(pane_id).map(|record| record.pane_type.clone()))
            })
    }

    fn editor_target_for_pane_type(pane_type: &PaneType) -> Option<ActiveEditorTarget> {
        match pane_type {
            PaneType::CodeSymbol => Some(ActiveEditorTarget::Code),
            PaneType::LoomWikiPage => Some(ActiveEditorTarget::Rich),
            _ => None,
        }
    }

    fn focused_editor_target(&self, ctx: &egui::Context) -> Option<ActiveEditorTarget> {
        let bus = crate::interop::InteractionBus::get_or_init(ctx);
        let focus_owner: Option<PaneId> =
            crate::interop::InteractionBus::with_try_lock(&bus, |b| b.focus_owner().cloned())
                .flatten();
        let focus_owner = focus_owner?;
        self.editor_target_for_pane(&focus_owner)
    }

    fn active_editor_target(&self, ctx: &egui::Context) -> Option<ActiveEditorTarget> {
        // Use the same focus authority as unified undo: the shell's explicit active pane wins, while
        // a genuinely focused detached viewport may supply its own bus owner. Preferring the raw bus
        // owner here lets a background editor's stale publication disable or misroute menu commands
        // for the active pane.
        self.active_pane
            .as_ref()
            .and_then(|pane_id| self.editor_target_for_pane(pane_id))
            .or_else(|| self.focused_editor_target(ctx))
    }

    /// Dispatch the one canonical shared Find command, then mount both native find engines while granting
    /// keyboard focus only to the operator's active pane. No callbacks are registered here: the bus owns a
    /// fixed lifecycle/query/result slot, so repeated commands and remounts cannot accumulate consumers.
    fn dispatch_shared_find_command(
        &mut self,
        ctx: &egui::Context,
        target: ActiveEditorTarget,
    ) -> bool {
        let bus = crate::interop::InteractionBus::get_or_init(ctx);
        let dispatched = crate::interop::InteractionBus::with_try_lock(&bus, |bus| {
            crate::interop::register_standard_commands(
                bus,
                crate::interop::EditorSurfaceKind::Code,
            );
            bus.dispatch_command(ctx, crate::interop::CMD_FIND)
        })
        .unwrap_or(false);
        if !dispatched {
            return false;
        }

        let code_panel = self.active_mounted_code_panel();
        let pattern = match target {
            ActiveEditorTarget::Code => {
                code_panel.open_find(false);
                let rich_state = self.active_rich_state();
                if let Ok(mut rich) = rich_state.lock() {
                    rich.open_find_replace_passive(false);
                }
                code_panel
                    .find_state()
                    .map(|find| find.query.pattern)
                    .unwrap_or_default()
            }
            ActiveEditorTarget::Rich => {
                code_panel.open_find_passive(false);
                let rich_state = self.active_rich_state();
                rich_state
                    .lock()
                    .ok()
                    .map(|mut rich| {
                        rich.open_find_replace_for_host(false);
                        rich.find_replace
                            .as_ref()
                            .map(|find| find.query.pattern.clone())
                            .unwrap_or_default()
                    })
                    .unwrap_or_default()
            }
        };
        self.apply_shared_find_query(ctx, pattern);
        ctx.request_repaint();
        true
    }

    /// Open the real MT-029 global Find-in-Files surface and join it to the mounted rich-document find
    /// lifecycle through the existing InteractionBus. The query remains owned by the rendered MT-029
    /// panel; this host bridge only observes it and publishes accepted backend rows.
    fn dispatch_shared_find_in_files_command(
        &mut self,
        ctx: &egui::Context,
        replace: bool,
    ) -> bool {
        if self.active_editor_target(ctx).is_none() {
            return false;
        }
        let bus = crate::interop::InteractionBus::get_or_init(ctx);
        let dispatched = crate::interop::InteractionBus::with_try_lock(&bus, |bus| {
            crate::interop::register_standard_commands(
                bus,
                crate::interop::EditorSurfaceKind::Code,
            );
            bus.dispatch_command(ctx, crate::interop::CMD_FIND)
        })
        .unwrap_or(false);
        if !dispatched {
            ctx.request_repaint();
            return false;
        }
        let rich_state = self.active_rich_state();
        if let Ok(mut rich) = rich_state.lock() {
            rich.open_find_replace_passive(replace);
        }
        let opened = self.open_content_on_active_pane(PaneType::FindInFiles, None);
        if !opened {
            let _ = crate::interop::InteractionBus::with_try_lock(&bus, |bus| {
                bus.close_shared_find();
            });
            return false;
        }
        self.shared_find_projection_key = None;
        ctx.request_repaint();
        true
    }

    /// Run one query through both shipped native find state machines and publish the typed result pair on
    /// the same InteractionBus. This is synchronous today, but the bus generation gate already rejects a
    /// stale future asynchronous result after rapid query replacement.
    fn apply_shared_find_query(&mut self, ctx: &egui::Context, pattern: String) {
        let bus = crate::interop::InteractionBus::get_or_init(ctx);
        let Some(query) = crate::interop::InteractionBus::with_try_lock(&bus, |bus| {
            bus.update_shared_find_query(pattern)
        }) else {
            ctx.request_repaint();
            return;
        };

        let code_panel = self.active_mounted_code_panel();
        if !code_panel.is_find_open() {
            code_panel.open_find_passive(false);
        }
        if code_panel
            .find_state()
            .is_some_and(|find| find.query.pattern != query.pattern)
        {
            code_panel.set_find_query(query.pattern.clone());
        }
        let code_hits = code_panel
            .find_state()
            .map(|find| find.matches.len())
            .unwrap_or_default();

        let rich_state = self.active_rich_state();
        let Some(note_hits) = rich_state.lock().ok().map(|mut rich| {
            if rich.find_replace.is_none() {
                rich.open_find_replace_passive(false);
            }
            if let Some(mut find) = rich.find_replace.take() {
                if find.query.pattern != query.pattern {
                    find.query.pattern = query.pattern.clone();
                }
                // Rescan even when the text is unchanged so document edits are reflected in the typed
                // result pair without waiting for another query edit.
                find.rescan(&rich.doc);
                let hits = find.scan.len();
                rich.find_replace = Some(find);
                hits
            } else {
                0
            }
        }) else {
            // A concurrent rich-editor operation owns the state this frame. Keep the current typed result
            // provisional and retry; never publish a fabricated zero-note result for lock contention.
            ctx.request_repaint();
            return;
        };

        let published = crate::interop::InteractionBus::with_try_lock(&bus, |bus| {
            bus.publish_shared_find_results(
                &query,
                crate::interop::SharedCodeFindResults {
                    entries: Vec::new(),
                    mounted_match_count: code_hits,
                },
                crate::interop::SharedNoteFindResults {
                    entries: Vec::new(),
                    mounted_match_count: note_hits,
                },
            )
        })
        .unwrap_or(false);
        if !published {
            ctx.request_repaint();
        }
    }

    /// Observe the rendered MT-029 state after the pane frame, project only current backend rows into
    /// typed code/note lanes, and run the same query through the mounted rich-document find engine.
    fn drive_shared_find_in_files(&mut self, ctx: &egui::Context) {
        let workspace_generation = self
            .find_in_files_shared
            .lock()
            .map(|shared| shared.workspace_generation)
            .unwrap_or_default();
        let state_handle = Arc::clone(&self.find_in_files_state);
        let active_pane = self.active_pane.clone();
        let Some((pattern, projection_key, projection)) =
            state_handle.lock().ok().and_then(|states| {
                let state = active_pane
                    .as_ref()
                    .and_then(|pane_id| states.get(pane_id))
                    .or_else(|| states.values().next())?;
                let pattern = state.query.clone();
                let current_search_key = state.current_search_key();
                let results_are_current = !pattern.trim().is_empty()
                    && !state.search_in_flight()
                    && state.result_set_key.as_deref() == Some(current_search_key.as_str());
                let projection_key = (
                    workspace_generation,
                    state.results_generation(),
                    pattern.clone(),
                    results_are_current,
                );
                let projection = (self.shared_find_projection_key.as_ref()
                    != Some(&projection_key))
                .then(|| {
                    if results_are_current {
                        crate::find_in_files::shared_editor_find_entries(&state.results)
                    } else {
                        (Vec::new(), Vec::new())
                    }
                });
                Some((pattern, projection_key, projection))
            })
        else {
            ctx.request_repaint();
            return;
        };
        let projection_changed = projection.is_some();
        if let Some((code, note)) = projection {
            self.shared_find_projection_key = Some(projection_key);
            self.shared_find_code_entries = code;
            self.shared_find_note_entries = note;
        }

        let rich_state = self.active_rich_state();
        let Some(note_hits) = rich_state.lock().ok().map(|mut rich| {
            if rich.find_replace.is_none() {
                rich.open_find_replace_passive(false);
            }
            if let Some(mut find) = rich.find_replace.take() {
                if find.query.pattern != pattern {
                    find.query.pattern = pattern.clone();
                }
                find.rescan(&rich.doc);
                let hits = find.scan.len();
                rich.find_replace = Some(find);
                hits
            } else {
                0
            }
        }) else {
            ctx.request_repaint();
            return;
        };

        let bus = crate::interop::InteractionBus::get_or_init(ctx);
        let published = crate::interop::InteractionBus::with_try_lock(&bus, |bus| {
            let query = bus.update_shared_find_query(pattern);
            if !projection_changed
                && bus.shared_find_results().query == query
                && bus.shared_find_results().note.mounted_match_count == note_hits
            {
                return true;
            }
            bus.publish_shared_find_results(
                &query,
                crate::interop::SharedCodeFindResults {
                    entries: self.shared_find_code_entries.clone(),
                    mounted_match_count: 0,
                },
                crate::interop::SharedNoteFindResults {
                    entries: self.shared_find_note_entries.clone(),
                    mounted_match_count: note_hits,
                },
            )
        })
        .unwrap_or(false);
        if !published {
            ctx.request_repaint();
        }
    }

    /// Post-render shared Find driver. Reading after pane rendering captures a query typed this frame. If
    /// the active pane closed its native find UI, the shared lifecycle closes instead of reopening it on
    /// the next frame (Escape remains lifecycle-safe).
    fn drive_shared_find(&mut self, ctx: &egui::Context) {
        let bus = crate::interop::InteractionBus::get_or_init(ctx);
        let Some(active) =
            crate::interop::InteractionBus::with_try_lock(&bus, |bus| bus.shared_find_is_active())
        else {
            ctx.request_repaint();
            return;
        };
        let global_find_active = self
            .active_pane
            .as_ref()
            .and_then(|pane_id| self.pane_type_for(pane_id))
            == Some(PaneType::FindInFiles);
        if active && global_find_active {
            self.drive_shared_find_in_files(ctx);
            return;
        }
        let Some(target) = self.active_editor_target(ctx) else {
            return;
        };
        let active_pattern = match target {
            ActiveEditorTarget::Code => self
                .active_mounted_code_panel()
                .find_state()
                .map(|find| find.query.pattern),
            ActiveEditorTarget::Rich => {
                let rich_state = self.active_rich_state();
                rich_state.lock().ok().and_then(|rich| {
                    rich.find_replace
                        .as_ref()
                        .map(|find| find.query.pattern.clone())
                })
            }
        };
        if !active {
            // A pane-local Ctrl+F is also an operator-facing Find entry. Detect the native panel opened by
            // that real shortcut, dispatch the same canonical bus command exactly once, and mount only the
            // inactive half passively. Menu/palette Find already activated the bus before reaching here.
            let Some(pattern) = active_pattern else {
                return;
            };
            let dispatched = crate::interop::InteractionBus::with_try_lock(&bus, |bus| {
                crate::interop::register_standard_commands(
                    bus,
                    crate::interop::EditorSurfaceKind::Code,
                );
                bus.dispatch_command(ctx, crate::interop::CMD_FIND)
            })
            .unwrap_or(false);
            if !dispatched {
                ctx.request_repaint();
                return;
            }
            match target {
                ActiveEditorTarget::Code => {
                    let rich_state = self.active_rich_state();
                    if let Ok(mut rich) = rich_state.lock() {
                        rich.open_find_replace_passive(false);
                    };
                }
                ActiveEditorTarget::Rich => {
                    self.active_mounted_code_panel().open_find_passive(false);
                }
            }
            self.apply_shared_find_query(ctx, pattern);
            return;
        }

        if let Some(pattern) = active_pattern {
            self.apply_shared_find_query(ctx, pattern);
        } else {
            // Shared Find closes as one lifecycle: Escape in the active pane must not leave the passive
            // half open, nor may that passive half auto-reactivate the command after focus changes.
            self.active_mounted_code_panel().close_find();
            let rich_state = self.active_rich_state();
            if let Ok(mut rich) = rich_state.lock() {
                rich.find_replace = None;
            }
            let _ = crate::interop::InteractionBus::with_try_lock(&bus, |bus| {
                bus.close_shared_find();
            });
        }
    }

    fn active_editor_pane_id(
        &self,
        ctx: &egui::Context,
        target: ActiveEditorTarget,
    ) -> Option<PaneId> {
        let bus = crate::interop::InteractionBus::get_or_init(ctx);
        if let Some(pane_id) =
            crate::interop::InteractionBus::with_try_lock(&bus, |b| b.focus_owner().cloned())
                .flatten()
                .filter(|pane_id| self.editor_target_for_pane(pane_id) == Some(target))
        {
            return Some(pane_id);
        }
        if let Some(pane_id) = self.active_pane.as_ref() {
            if self.editor_target_for_pane(pane_id) == Some(target) {
                return Some(pane_id.clone());
            }
        }
        None
    }

    fn dispatch_clipboard_editor_command(
        &mut self,
        ctx: &egui::Context,
        target: ActiveEditorTarget,
        command_id: &str,
    ) -> bool {
        use crate::command_registry as cr;
        match (target, command_id) {
            (ActiveEditorTarget::Code, cr::CMD_EDITOR_EDIT_COPY) => {
                self.copy_code_selection_to_bus(ctx, false)
            }
            (ActiveEditorTarget::Code, cr::CMD_EDITOR_EDIT_CUT) => {
                self.copy_code_selection_to_bus(ctx, true)
            }
            (ActiveEditorTarget::Code, cr::CMD_EDITOR_EDIT_PASTE) => self.paste_bus_into_code(ctx),
            (ActiveEditorTarget::Rich, cr::CMD_EDITOR_EDIT_COPY) => {
                self.copy_rich_selection_to_bus(ctx, false)
            }
            (ActiveEditorTarget::Rich, cr::CMD_EDITOR_EDIT_CUT) => {
                self.copy_rich_selection_to_bus(ctx, true)
            }
            (ActiveEditorTarget::Rich, cr::CMD_EDITOR_EDIT_PASTE) => self.paste_bus_into_rich(ctx),
            _ => false,
        }
    }

    fn copy_code_selection_to_bus(&mut self, ctx: &egui::Context, cut: bool) -> bool {
        let Some(pane_id) = self.active_editor_pane_id(ctx, ActiveEditorTarget::Code) else {
            return false;
        };
        let panel = self.active_mounted_code_panel();
        let sink = crate::rich_editor::properties::metadata_client::EguiClipboard::new(ctx.clone());
        let bus = crate::interop::InteractionBus::get_or_init(ctx);
        let copied = crate::interop::InteractionBus::with_try_lock(&bus, |b| {
            crate::code_editor::interop_adapter::register(b);
            crate::code_editor::interop_adapter::copy_to_bus(b, &panel, pane_id.clone(), &sink)
        })
        .unwrap_or(false);
        if !copied || !cut {
            return copied;
        }

        let before = panel.buffer();
        let deleted = panel.delete_text();
        if deleted > 0 {
            let after = panel.buffer();
            let pane_id_for_undo = pane_id.clone();
            crate::interop::InteractionBus::with_try_lock(&bus, |b| {
                crate::code_editor::interop_adapter::push_code_edit_undo(
                    b,
                    pane_id_for_undo,
                    &panel,
                    before,
                    after,
                    "code: cut",
                );
            });
        }
        copied
    }

    fn paste_bus_into_code(&mut self, ctx: &egui::Context) -> bool {
        let Some(pane_id) = self.active_editor_pane_id(ctx, ActiveEditorTarget::Code) else {
            return false;
        };
        let panel = self.active_mounted_code_panel();
        let before = panel.buffer();
        let bus = crate::interop::InteractionBus::get_or_init(ctx);
        let applied = crate::interop::InteractionBus::with_try_lock(&bus, |b| {
            crate::code_editor::interop_adapter::register(b);
            crate::code_editor::interop_adapter::paste_from_bus(b, &panel)
        })
        .unwrap_or(0);
        if applied == 0 {
            return false;
        }
        let after = panel.buffer();
        crate::interop::InteractionBus::with_try_lock(&bus, |b| {
            crate::code_editor::interop_adapter::push_code_edit_undo(
                b,
                pane_id,
                &panel,
                before,
                after,
                "code: paste",
            );
        });
        true
    }

    fn copy_rich_selection_to_bus(&mut self, ctx: &egui::Context, cut: bool) -> bool {
        let text = {
            let rich_state = self.active_rich_state();
            let Ok(state) = rich_state.lock() else {
                return false;
            };
            state.selected_text().map(|(_, _, _, text)| text)
        };
        let Some(text) = text else {
            return false;
        };
        let sink = crate::rich_editor::properties::metadata_client::EguiClipboard::new(ctx.clone());
        let bus = crate::interop::InteractionBus::get_or_init(ctx);
        let copied = crate::interop::InteractionBus::with_try_lock(&bus, |b| {
            crate::rich_editor::interop_adapter::register(b);
            crate::rich_editor::interop_adapter::copy_text_to_bus(b, &text, &sink)
        })
        .unwrap_or(false);
        if copied && cut {
            let rich_state = self.active_rich_state();
            if let Ok(mut state) = rich_state.lock() {
                let _ = state.delete_selection_for_host();
            };
        }
        copied
    }

    fn paste_bus_into_rich(&mut self, ctx: &egui::Context) -> bool {
        let bus = crate::interop::InteractionBus::get_or_init(ctx);
        let text = crate::interop::InteractionBus::with_try_lock(&bus, |b| {
            crate::rich_editor::interop_adapter::register(b);
            crate::rich_editor::interop_adapter::paste_text_from_bus(b)
        })
        .flatten();
        let Some(text) = text else {
            return false;
        };
        let rich_state = self.active_rich_state();
        let Ok(mut state) = rich_state.lock() else {
            return false;
        };
        state.insert_plain_text_for_host(&text)
    }

    fn editor_target_for_pane(&self, pane_id: &PaneId) -> Option<ActiveEditorTarget> {
        self.pane_type_for(pane_id)
            .as_ref()
            .and_then(Self::editor_target_for_pane_type)
    }

    /// WP-KERNEL-012 MT-071: whether the FOCUSED pane this frame is the mounted code editor
    /// (`PaneType::CodeSymbol`). Reads the MT-035 [`InteractionBus`](crate::interop::InteractionBus)
    /// focus owner (the SAME focus seam the unified-undo enable predicates use) and resolves it against
    /// the pane registry. The editor status-bar segments render ONLY when this is true, so they HIDE the
    /// moment a non-code pane takes focus (AC-005) and never carry stale editor metadata. A contended bus
    /// lock or poisoned registry fails closed (no segments this frame, re-evaluated next frame).
    fn focused_pane_is_code_editor(&self, ctx: &egui::Context) -> bool {
        self.focused_editor_target(ctx) == Some(ActiveEditorTarget::Code)
    }

    /// WP-KERNEL-012 MT-071: the live editor file-metadata snapshot for the status-bar segments, or
    /// `None` when the focused pane is NOT a code editor (so the cluster hides — AC-005). Built each frame
    /// from the SAME mounted [`CodeEditorPanel`](crate::code_editor::panel::CodeEditorPanel) the host
    /// drives (the single doc-model source of truth — RISK-004), so the segments reflect the active
    /// document's real language / EOL / indent / encoding / whitespace state and never a parallel store.
    fn editor_segment_state(&self, ctx: &egui::Context) -> Option<EditorMetaSegmentState> {
        if !self.focused_pane_is_code_editor(ctx) {
            return None;
        }
        Some(EditorMetaSegmentState::from_panel(
            &self.active_mounted_code_panel(),
        ))
    }

    /// WP-KERNEL-012 MT-071: apply a typed [`EditorSegmentAction`] the status-bar segment emitted back
    /// onto the FOCUSED code document's MT-010 model (the "segment reports, the shell applies" discipline
    /// — RISK-004). Each arm routes to the existing panel mutator: language override, single-undo EOL
    /// convert, indent style (flips the Tab key), in-process encoding reopen (surfacing the typed `Err`),
    /// render-whitespace flip, or clipboard copy. Returns `true` when the action mutated state worth a
    /// repaint. NO backend call (the encoding reopen is the in-process MT-010 re-decode — RISK-005).
    fn apply_editor_segment_action(
        &self,
        ctx: &egui::Context,
        action: EditorSegmentAction,
    ) -> bool {
        let panel = self.active_mounted_code_panel();
        match action {
            EditorSegmentAction::SetLanguage(lang) => {
                panel.set_language_override(Some(lang));
                true
            }
            EditorSegmentAction::ConvertEol(eol) => panel.convert_eol(eol),
            EditorSegmentAction::SetIndent(style) => {
                panel.set_indent_style(style);
                true
            }
            EditorSegmentAction::ReopenWithEncoding(encoding) => {
                match panel.reopen_with_encoding(encoding) {
                    Ok(()) => true,
                    Err(message) => {
                        // Surface the typed reopen failure (e.g. in-memory buffer with no file path) as an
                        // honest non-fatal note rather than a silent no-op — the encoding does not change.
                        eprintln!("MT-071 reopen-with-encoding: {message}");
                        false
                    }
                }
            }
            EditorSegmentAction::SetRenderWhitespace(on) => {
                panel.set_render_whitespace(on);
                true
            }
            EditorSegmentAction::CopySegmentText(text) => {
                ctx.copy_text(text);
                true
            }
        }
    }

    /// WP-KERNEL-012 MT-079: the shared session-context cell the editor mounts read each frame (tests
    /// assert the shell pushed the active workspace + runtime into it so the editors thread real session
    /// context on mount — AC-079-2).
    pub fn editor_session_context(&self) -> SharedSessionContext {
        Arc::clone(&self.editor_mounts.session)
    }

    /// WP-KERNEL-012 MT-079: the last code-editor host-routed command the shell drained (Save /
    /// OpenCommandPalette). `None` until one is dispatched. The dispatch-observability surface for the
    /// AC-079-3 Save path. The host now snapshots and atomically writes the active disk-backed code
    /// buffer off the UI thread before advancing its saved-version watermark.
    pub fn last_editor_command(&self) -> Option<&CodeEditorAction> {
        self.last_editor_command.as_ref()
    }

    /// Whether a dirty code tab is waiting for explicit Save/Discard/Cancel confirmation.
    #[doc(hidden)]
    pub fn pending_dirty_code_close_for_test(&self) -> bool {
        self.pending_dirty_code_tab_close.is_some()
    }

    /// Drive the same close request used by FILE > Close Tab and the tab close button.
    #[doc(hidden)]
    pub fn close_active_tab_for_test(&mut self) -> bool {
        self.close_active_tab()
    }

    /// Confirm Discard on the current dirty-code close prompt (test seam over the dialog action).
    #[doc(hidden)]
    pub fn discard_pending_dirty_code_close_for_test(&mut self) -> bool {
        let Some(document_key) = self.pending_dirty_code_tab_close.take() else {
            return false;
        };
        let Some((pane_id, index)) = self.find_code_tab_by_document_key(&document_key) else {
            return false;
        };
        let closed = self.close_tab_now(pane_id, index);
        if closed {
            self.resume_pending_tab_close_batch();
        }
        closed
    }

    /// Confirm Cancel on the current dirty-code close prompt.
    #[doc(hidden)]
    pub fn cancel_pending_dirty_code_close_for_test(&mut self) -> bool {
        if self.pending_dirty_code_tab_close.take().is_none() {
            return false;
        }
        self.pending_tab_close_batch.clear();
        self.quick_switcher_nav_status = None;
        true
    }

    /// Confirm Save on the current dirty-code close prompt. The exact document remains open until the
    /// asynchronous atomic save succeeds.
    #[doc(hidden)]
    pub fn save_pending_dirty_code_close_for_test(&mut self) -> bool {
        self.confirm_pending_dirty_code_close_save()
    }

    /// Drive the same stable Close All/Close Others reconciliation used by tab-bar intents.
    #[doc(hidden)]
    pub fn close_tab_indices_for_test(&mut self, pane_id: PaneId, indices: Vec<usize>) {
        let targets: Vec<PendingTabCloseTarget> = indices
            .into_iter()
            .filter_map(|index| {
                self.tab_bar_states
                    .get(&pane_id)
                    .and_then(|bar| bar.tabs.get(index))
                    .map(|tab| PendingTabCloseTarget {
                        pane_id: pane_id.clone(),
                        pane_type: tab.pane_type.clone(),
                        content_id: tab.content_id.clone(),
                    })
            })
            .collect();
        self.pending_tab_close_batch.extend(targets);
        self.resume_pending_tab_close_batch();
    }

    /// Configure the durable participant identity used by every subsequently mounted native rich
    /// document SaveManager. This is a production host/session surface (parallel native-editor hosts
    /// call it before mounting documents), not a test-only mutation of RichEditorState internals.
    /// Rebinding after a save context exists is rejected so an in-flight/conflicted session cannot
    /// silently change attribution halfway through its receipt lineage.
    pub fn set_native_editor_participant_actor_id(
        &mut self,
        actor_id: impl Into<String>,
    ) -> Result<(), String> {
        let actor_id = actor_id.into();
        let actor_id = actor_id.trim();
        if actor_id.is_empty() {
            return Err("native editor participant actor id must not be empty".to_owned());
        }
        if self
            .editor_mounts
            .rich_documents
            .states()
            .iter()
            .any(|state| {
                state
                    .lock()
                    .map(|state| state.save.is_some())
                    .unwrap_or(true)
            })
        {
            return Err(
                "native editor participant actor id must be configured before rich documents mount"
                    .to_owned(),
            );
        }
        self.native_editor_participant_actor_id = actor_id.to_owned();
        Ok(())
    }

    /// Current participant identity used for future native rich-document save bindings.
    pub fn native_editor_participant_actor_id(&self) -> &str {
        &self.native_editor_participant_actor_id
    }

    /// Test-only: point the MT-021 backend clients (SCM, canvas, Loom-block) at an arbitrary `base_url`
    /// bridged onto `handle`, so a test can drive `apply_*_event` against a localhost capture server and
    /// assert the EXACT URL + body reaches the wire through the REAL app dispatch path. Production code
    /// never calls this (it uses [`set_runtime_handle`](Self::set_runtime_handle) -> hardcoded backend
    /// URL); it exists so the MAJOR #1/#2/#3 "client genuinely consumed by the app" proof is end-to-end.
    pub fn set_backend_base_url_for_test(
        &mut self,
        base_url: &str,
        handle: tokio::runtime::Handle,
    ) {
        self.quick_switcher_transport = Some(Arc::new(
            crate::quick_switcher::LoomGraphSearchClient::new(base_url, handle.clone()),
        ));
        self.quick_switcher_search = crate::quick_switcher::SearchManager::default();
        if let Ok(mut slot) = self.quick_switcher_results_cell.lock() {
            *slot = None;
        }
        if let Ok(mut slot) = self.quick_switcher_recents_cell.lock() {
            *slot = None;
        }
        if let Ok(mut slot) = self.quick_switcher_record_recent_cell.lock() {
            *slot = None;
        }
        self.loom_block_client = Some(crate::backend_client::LoomBlockClient::new(
            base_url,
            handle.clone(),
        ));
        self.source_control_client = Some(crate::backend_client::SourceControlClient::new(
            base_url,
            handle.clone(),
        ));
        self.canvas_client = Some(crate::backend_client::CanvasClient::new(
            base_url,
            handle.clone(),
        ));
        self.model_session_launch_client = Some(
            crate::backend_client::ModelSessionLaunchClient::new(base_url, handle.clone()),
        );
        // MT-024: the drawer card-action client too, so the confirm-discard -> DELETE wire test (mirroring
        // PROOF-024-2(e)) can drive the REAL dispatch path against a localhost capture server.
        self.drawer_action_client = Some(crate::backend_client::DrawerActionClient::new(
            base_url,
            handle.clone(),
        ));
        self.atelier_side_panel
            .bind_client(crate::backend_client::AtelierClient::new(
                base_url,
                handle.clone(),
            ));
        // MT-028 remediation: the mounted Loom Search factory owns its transport client just like
        // Find-in-Files. Rebind the concrete factory too, otherwise a managed-runtime proof (and any
        // future explicit backend adapter) changes the app clients while Loom Search silently keeps
        // calling the production default URL.
        self.factories.insert(
            PaneType::LoomSearchV2,
            Box::new(crate::loom_search_v2::LoomSearchV2PaneFactory::new(
                crate::backend_client::LoomSearchV2Client::new(base_url, handle.clone()),
                Arc::clone(&self.loom_search_v2_shared),
            )),
        );
        // MT-029: the mounted Find-in-Files factory owns its clients, so rebinding the app test backend
        // must replace that concrete factory too. Otherwise a production-mounted integration proof still
        // talks to the hard-coded production URL while every other app client uses the managed backend.
        let find_in_files_factory = crate::find_in_files::FindInFilesPaneFactory::new(
            crate::backend_client::WorkspaceSearchClient::new(base_url, handle.clone()),
            crate::backend_client::RichDocClient::new(base_url, handle.clone()),
            Arc::clone(&self.find_in_files_shared),
        );
        self.find_in_files_state = find_in_files_factory.states_handle();
        self.shared_find_projection_key = None;
        self.shared_find_code_entries.clear();
        self.shared_find_note_entries.clear();
        self.factories
            .insert(PaneType::FindInFiles, Box::new(find_in_files_factory));
        // MT-034/MT-065: Quick Switcher search and the follow-up code-symbol resolver are one
        // production navigation path. Keep both clients on the same explicitly bound backend;
        // otherwise a managed-runtime search can return an entity from `base_url` and Enter can
        // silently point-get that same id from the production default instead.
        self.install_mounted_code_nav_client_for_test(CodeNavClient::new(base_url));
        self.rich_doc_base_url = base_url.to_owned();
        if let Ok(mut session) = self.editor_mounts.session.lock() {
            session.backend_base_url = base_url.to_owned();
        }
        for rich_state in self.editor_mounts.rich_documents.states() {
            rich_state
                .lock()
                .unwrap_or_else(|poisoned| poisoned.into_inner())
                .rebind_wikilink_backend_for_test(base_url);
        }
        if let Ok(mut slot) = self.rich_doc_load_cell.lock() {
            slot.clear();
        }
        self.rich_doc_load_generation = self.rich_doc_load_generation.wrapping_add(1);
        self.rich_doc_loads.clear();
        self.left_rail
            .project_tree
            .set_backend_base_url_for_test(base_url, &handle);
        self.runtime_handle = Some(handle);
    }

