    #[test]
    fn host_yields_on_rebind_contention_then_clears_stale_workspace_route() {
        let ctx = egui::Context::default();
        let mut app = HandshakeApp::with_health(HealthDisplayState::Error(
            "workspace-rebind-isolation-test".to_owned(),
        ));
        app.bind_active_project_for_integration_test("workspace-b");
        let bus = crate::interop::InteractionBus::get_or_init(&ctx);

        let mut guard = bus.lock().expect("lock interaction bus for contention");
        assert!(guard.bind_workspace("workspace-a"));
        guard.request_open_document("workspace-a-document");

        let output = ctx.run(egui::RawInput::default(), |ctx| app.ui(ctx));
        drop(output);
        assert_eq!(
            guard.pending_navigation(),
            Some("workspace-a-document"),
            "a contended bind yields the frame without draining the old workspace route"
        );
        drop(guard);

        let output = ctx.run(egui::RawInput::default(), |ctx| app.ui(ctx));
        drop(output);
        let mut guard = bus.lock().expect("inspect rebound interaction bus");
        assert_eq!(guard.workspace_id(), "workspace-b");
        assert!(
            guard.take_pending_navigation().is_none(),
            "the successful host rebind clears A before B can render or drain routes"
        );
    }

