    #[test]
    fn fems_review_refresh_failure_renders_and_dispatches_retry_by_accesskit() {
        let listener = std::net::TcpListener::bind("127.0.0.1:0")
            .expect("bind counted FEMS review-list server");
        let base_url = format!("http://{}", listener.local_addr().unwrap());
        let (request_tx, request_rx) = std::sync::mpsc::channel::<String>();
        let (stop_tx, stop_rx) = std::sync::mpsc::channel::<()>();
        let server = std::thread::spawn(move || {
            for (status, body) in [
                ("500 Internal Server Error", r#"{"error":"forced"}"#),
                ("200 OK", "[]"),
            ] {
                let (mut stream, _) = listener.accept().expect("accept FEMS list request");
                let mut request = Vec::new();
                let mut chunk = [0_u8; 1024];
                while !request.windows(4).any(|bytes| bytes == b"\r\n\r\n") {
                    let read = std::io::Read::read(&mut stream, &mut chunk)
                        .expect("read FEMS list request");
                    assert!(read > 0, "FEMS list request closed before its headers");
                    request.extend_from_slice(&chunk[..read]);
                }
                let request_line = String::from_utf8_lossy(&request)
                    .lines()
                    .next()
                    .unwrap_or_default()
                    .to_owned();
                request_tx.send(request_line).unwrap();
                let response = format!(
                    "HTTP/1.1 {status}\r\nContent-Type: application/json\r\nContent-Length: {}\r\nConnection: close\r\n\r\n{body}",
                    body.len()
                );
                std::io::Write::write_all(&mut stream, response.as_bytes())
                    .expect("write FEMS list response");
            }

            listener
                .set_nonblocking(true)
                .expect("make FEMS server nonblocking for duplicate detection");
            loop {
                if stop_rx.try_recv().is_ok() {
                    break;
                }
                match listener.accept() {
                    Ok((mut stream, _)) => {
                        let mut request = [0_u8; 1024];
                        let read = std::io::Read::read(&mut stream, &mut request)
                            .expect("read duplicate FEMS list request");
                        let request_line = String::from_utf8_lossy(&request[..read])
                            .lines()
                            .next()
                            .unwrap_or_default()
                            .to_owned();
                        request_tx.send(request_line).unwrap();
                        let body = "[]";
                        let response = format!(
                            "HTTP/1.1 200 OK\r\nContent-Type: application/json\r\nContent-Length: {}\r\nConnection: close\r\n\r\n{body}",
                            body.len()
                        );
                        let _ = std::io::Write::write_all(&mut stream, response.as_bytes());
                    }
                    Err(error) if error.kind() == std::io::ErrorKind::WouldBlock => {
                        std::thread::sleep(std::time::Duration::from_millis(2));
                    }
                    Err(error) => {
                        let _ = request_tx
                            .send(format!("SERVER_ERROR duplicate FEMS list accept: {error}"));
                        break;
                    }
                }
            }
        });

        let runtime = tokio::runtime::Builder::new_multi_thread()
            .worker_threads(1)
            .enable_all()
            .build()
            .expect("build FEMS retry test runtime");
        let mut app = HandshakeApp::with_health(HealthDisplayState::Error("offline".to_owned()));
        app.set_runtime_handle(runtime.handle().clone());
        app.rich_doc_base_url = base_url;

        let mut harness = Harness::builder().build_state(
            |ctx, app: &mut HandshakeApp| app.drive_propose_to_memory(ctx),
            app,
        );
        let ctx = harness.ctx.clone();
        harness.state_mut().refresh_pending_memory_proposal_reviews(
            &ctx,
            "workspace-a".to_owned(),
            7,
        );
        let expected = "GET /workspaces/workspace-a/memory/proposals?limit=200 HTTP/1.1";
        assert_eq!(
            request_rx
                .recv_timeout(std::time::Duration::from_secs(2))
                .expect("initial canonical FEMS list request"),
            expected
        );
        for _ in 0..100 {
            harness.run_steps(1);
            if harness.root().children_recursive().any(|node| {
                node.accesskit_node().author_id()
                    == Some(crate::fems::memory_proposal::FEMS_REVIEW_REFRESH_RETRY_AUTHOR_ID)
            }) {
                break;
            }
            std::thread::sleep(std::time::Duration::from_millis(2));
        }
        let retry = harness
            .root()
            .children_recursive()
            .find(|node| {
                node.accesskit_node().author_id()
                    == Some(crate::fems::memory_proposal::FEMS_REVIEW_REFRESH_RETRY_AUTHOR_ID)
            })
            .expect("failed canonical refresh mounts the stable FEMS retry control");
        assert_eq!(retry.accesskit_node().role(), egui::accesskit::Role::Button);
        retry.click_accesskit();
        harness.run_steps(1);
        assert_eq!(
            request_rx
                .recv_timeout(std::time::Duration::from_secs(2))
                .expect("AccessKit retry dispatches the canonical FEMS list request"),
            expected
        );

        for _ in 0..100 {
            harness.run_steps(1);
            if harness.state().memory_proposal_review_refresh.is_none() {
                break;
            }
            std::thread::sleep(std::time::Duration::from_millis(2));
        }

        assert!(
            harness.state().memory_proposal_review_retry.is_none(),
            "the AccessKit click consumes the single armed retry"
        );
        assert_eq!(
            harness.state().memory_proposal_review_refresh,
            None,
            "the successful retry drains the canonical pending-list refresh"
        );
        assert!(
            harness
                .state()
                .memory_proposal_review_refresh_deferred
                .is_none(),
            "a single retry click must not enqueue a duplicate deferred refresh"
        );
        assert!(
            !harness.root().children_recursive().any(|node| {
                node.accesskit_node().author_id()
                    == Some(crate::fems::memory_proposal::FEMS_REVIEW_REFRESH_RETRY_AUTHOR_ID)
            }),
            "the successful retry removes the conditional AccessKit retry control"
        );
        harness.run_steps(4);
        std::thread::sleep(std::time::Duration::from_millis(20));
        stop_tx.send(()).unwrap();
        server.join().expect("join counted FEMS review-list server");
        assert!(
            request_rx.try_recv().is_err(),
            "one AccessKit click must dispatch exactly one retry GET"
        );
    }

    #[test]
